insert into public.products (id, name, slug, image_url, short_description, description, recommendation, recommend_points, affiliate_url, category_id, published, featured, tags, created_at, updated_at) values ('00000002-0000-4000-8000-000000000015', '무선 미니 가습기', 'item-15', 'https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=format&fit=crop&w=900&q=80', '내 책상에 놓는 작은 촉촉함', '무선 미니 가습기을 소개하는 샘플 콘텐츠입니다. 사진은 분위기 연출용이며 실제 판매 상품과 다릅니다. 운영 전 실제 상품 사진과 설명으로 교체해 주세요.', '일상의 작은 불편을 줄여 주는 아이디어가 마음에 들었어요. 내 생활에 잘 맞는지 확인하고 골라보세요.', ARRAY['작은 크기','간단한 조작','손쉬운 관리']::text[], 'https://www.coupang.com/', '00000001-0000-4000-8000-000000000001', true, false, ARRAY['생활','추천템','샘플']::text[], '2026-09-01T03:00:00+00:00', '2026-09-01T03:00:00+00:00') on conflict (id) do nothing;
insert into public.videos (id, title, slug, platform, video_url, thumbnail_url, description, published, featured, sort_order, tags, published_at, created_at, updated_at) values ('00000003-0000-4000-8000-000000000001', '작은 주방, 잘 쓰는 살림템 3가지', 'log-01', 'instagram', 'https://www.instagram.com/', 'https://images.unsplash.com/photo-1556911220-bff31c812dba?auto=format&fit=crop&w=900&q=80', '한솔이 골라본 일상의 작은 추천템. 이 영상은 화면 확인을 위한 샘플입니다. 운영 전에 원본 영상 링크와 썸네일을 등록해 주세요.', true, true, 0, ARRAY['샘플','살림','일상','주방']::text[], '2026-09-09T03:00:00+00:00', '2026-09-01T03:00:00+00:00', '2026-09-01T03:00:00+00:00') on conflict (id) do nothing;
