insert into public.settings (id, site_name, site_description, instagram_url, youtube_url, affiliate_disclosure, footer_text, default_seo_title, default_seo_description, logo_url, contact_email) values (1, '핫템로그', '인스타 릴스와 유튜브 쇼츠에서 소개한 추천템을 한곳에 모았습니다.', 'https://www.instagram.com/', 'https://www.youtube.com/', '이 포스팅은 쿠팡 파트너스 활동의 일환으로, 이에 따른 일정액의 수수료를 제공받을 수 있습니다.', '오늘의 핫템을 기록합니다. © Hottem Log.', '핫템로그 | 영상에서 본 추천템 모음', '인스타 릴스와 유튜브 쇼츠에서 소개한 추천 제품을 한곳에서 확인하세요.', '', '') on conflict (id) do nothing;
